-- UniClass V5 — Daily Math Power-Up Question Bank
-- Schema migration for teacher-approved foundation questions.
-- Apply this AFTER the existing UniClass V5 migrations.

create table if not exists public.foundation_questions (
  id uuid primary key default gen_random_uuid(),
  question_id text not null unique,
  level smallint not null check (level between 1 and 3),
  skill text not null,
  domain text not null,
  difficulty text not null check (difficulty in ('Easy','Medium','Challenge')),
  question text not null,
  options jsonb not null check (jsonb_typeof(options) = 'array' and jsonb_array_length(options) = 4),
  correct_index smallint not null check (correct_index between 0 and 3),
  correct_answer text not null,
  answer_explanation text not null,
  student_feedback text not null default '',
  tags text,
  review_status text not null default 'APPROVED' check (review_status in ('REVIEW','APPROVED','REVISE','REJECT')),
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists idx_foundation_questions_active_level
  on public.foundation_questions(level, is_active)
  where is_active;

create index if not exists idx_foundation_questions_active_skill
  on public.foundation_questions(skill, is_active)
  where is_active;

create index if not exists idx_foundation_questions_approved
  on public.foundation_questions(review_status, is_active)
  where review_status = 'APPROVED' and is_active;

alter table public.foundation_questions enable row level security;

-- Teachers can inspect the approved bank for their Mathematics classroom(s).
drop policy if exists "teachers_read_foundation_questions" on public.foundation_questions;
create policy "teachers_read_foundation_questions"
on public.foundation_questions
for select to authenticated
using (
  exists (
    select 1
    from public.classrooms c
    where c.teacher_id = auth.uid()
  )
);

-- Students do NOT receive direct table access. The daily-mission security-definer
-- function selects the approved bank rows and materialises only the safe question
-- content into public.missions.ai_content.

revoke all on public.foundation_questions from anon, authenticated;
grant select on public.foundation_questions to authenticated;

-- Re-grant is paired with RLS; the policy above is the gate.

comment on table public.foundation_questions is
  'Teacher-approved question bank for UniClass Daily Math Power-Up. Student clients should receive questions only through missions.ai_content.';
comment on column public.foundation_questions.correct_index is
  'Zero-based option index used by the existing UniClass multiple-choice grading pipeline.';
comment on column public.foundation_questions.answer_explanation is
  'Student-facing explanation of why the correct answer is correct.';
comment on column public.foundation_questions.student_feedback is
  'Short remediation/encouragement shown after an incorrect response.';


