-- UniClass V5 — Daily Math Power-Up engine backed by the approved question bank.
-- This replaces the generated-number drill while preserving the existing
-- public.missions + MissionAssessment + submit_mission pipeline.

alter table public.missions
  add column if not exists mission_source text not null default 'teacher_created';

alter table public.missions
  add column if not exists foundation_levels smallint[];

alter table public.missions
  add column if not exists foundation_skills text[];

alter table public.missions
  add column if not exists foundation_bank_version text;

alter table public.missions
  drop constraint if exists missions_mission_source;

alter table public.missions
  add constraint missions_mission_source
  check (mission_source in ('teacher_created','daily_foundation'));

create index if not exists idx_missions_source_daily_foundation
  on public.missions(classroom_id, auto_daily_date)
  where mission_source = 'daily_foundation';

-- The existing migration already creates ensure_daily_drill_for_student().
-- Replacing ensure_daily_drill() here keeps the student-facing API unchanged.
create or replace function public.ensure_daily_drill(p_classroom_id uuid default null)
returns public.missions
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user uuid := auth.uid();
  v_today date := (now() at time zone 'Asia/Manila')::date;
  v_end timestamptz := ((now() at time zone 'Asia/Manila')::date + time '23:59:59') at time zone 'Asia/Manila';
  v_classroom public.classrooms%rowtype;
  v_existing public.missions%rowtype;
  v_mission public.missions%rowtype;
  v_subject text;
  v_is_math boolean;
  v_items jsonb := '[]'::jsonb;
  v_item jsonb;
  v_answers jsonb := '[]'::jsonb;
  v_levels smallint[] := '{}'::smallint[];
  v_skills text[] := '{}'::text[];
  v_row record;
  v_i integer := 0;
begin
  if v_user is null then raise exception 'Authentication required'; end if;

  select * into v_classroom
  from public.classrooms
  where id = coalesce(
    p_classroom_id,
    (select classroom_id
       from public.group_accounts
      where user_id = v_user and is_approved = true
      order by created_date asc limit 1)
  );

  if not found then raise exception 'Classroom not found'; end if;

  if not auth_is_teacher_of(v_classroom.id) then
    if not exists (
      select 1
      from public.group_accounts
      where user_id = v_user
        and classroom_id = v_classroom.id
        and is_approved = true
    ) then
      raise exception 'Approved classroom account required';
    end if;
  end if;

  select * into v_existing
  from public.missions
  where is_auto_daily
    and auto_daily_date = v_today
    and classroom_id = v_classroom.id
    and coalesce(subject, '') = coalesce(nullif(trim(v_classroom.subject), ''), 'General Studies');

  if found then return v_existing; end if;

  v_subject := coalesce(nullif(trim(v_classroom.subject), ''), 'General Studies');
  v_is_math := lower(v_subject) ~ '(math|matemat|mathemat|maths|mathematics|arithmetic|algebra|geometry)';

  if not v_is_math then
    raise exception 'Automatic Daily Math Power-Up is available for Mathematics classes only. Classroom subject: %s', v_subject;
  end if;

  -- Daily mix: 2 Level-1 + 2 Level-2 + 1 Level-3 questions.
  -- Each selected row is APPROVED and ACTIVE. The correct answer is converted
  -- to the zero-based index already used by submit_mission().
  for v_row in
    (
      select *
      from (
        select fq.*, row_number() over (partition by fq.level order by random()) as rn
        from public.foundation_questions fq
        where fq.review_status = 'APPROVED'
          and fq.is_active
          and fq.level in (1,2,3)
      ) q
      where (level = 1 and rn <= 2)
         or (level = 2 and rn <= 2)
         or (level = 3 and rn <= 1)
      order by random()
      limit 5
    )
  loop
    v_i := v_i + 1;
    v_levels := array_append(v_levels, v_row.level);
    v_skills := array_append(v_skills, v_row.skill);

    v_item := jsonb_build_object(
      'id', v_i,
      'question_id', v_row.question_id,
      'level', v_row.level,
      'skill', v_row.skill,
      'domain', v_row.domain,
      'difficulty', v_row.difficulty,
      'prompt', v_row.question,
      'question', v_row.question,
      'options', v_row.options,
      'answer_index', v_row.correct_index,
      'explanation', v_row.answer_explanation,
      'feedback', v_row.student_feedback
    );

    v_items := v_items || jsonb_build_array(v_item);
    v_answers := v_answers || jsonb_build_array(v_row.correct_index);
  end loop;

  if v_i < 5 then
    raise exception 'Daily Math Power-Up question bank does not contain enough approved active questions for all Levels 1–3';
  end if;

    classroom_id,
    title,
    description,
    xp_reward,
    max_score,
    deadline,
    deadline_at,
    is_active,
    created_by,
    formative_type,
    ai_content,
    answer_key,
    is_auto_daily,
    auto_daily_date,
    subject,
    mission_source,
    foundation_levels,
    foundation_skills,
    foundation_bank_version
  )
  values (
    v_classroom.id,
    'Daily Math Power-Up',
    'Five quick foundation questions to strengthen your everyday math skills. Complete today''s Power-Up to earn 5 XP.',
    5,
    5,
    v_today,
    v_end,
    true,
    v_classroom.teacher_id,
    'multiple_choice',
    jsonb_build_object(
      'questions', v_items,
      'auto_generated', true,
      'mission_source', 'daily_foundation',
      'learning_target', 'I can strengthen the basic math skills I need for today''s lessons.',
      'student_instructions', 'Answer all five questions. Read the explanation after you finish to learn from each answer.',
      'estimated_minutes', 5,
      'foundation_levels', to_jsonb(v_levels),
      'foundation_skills', to_jsonb(v_skills),
      'question_bank_version', 'v1-approved-3100'
    )::text,
    jsonb_build_object('answers', v_answers)::text,
    true,
    v_today,
    v_subject,
    'daily_foundation',
    v_levels,
    v_skills,
    'v1-approved-3100'
  )
  returning * into v_mission;

  return v_mission;
end;
$$;

revoke all on function public.ensure_daily_drill(uuid) from public;
grant execute on function public.ensure_daily_drill(uuid) to authenticated;

-- Student access continues through the existing ensure_daily_drill_for_student()
-- wrapper, so no new client-side RPC is required.
